mapper.select:
select id, catalog_code as catalogCode, catalog_name as catalogName, course_name as courseName, chapter_code as chapterCode, chapter_name as chapterName, question_count as questionCount from edu_question_catalog where status = '0'
and course_name = #{courseName}
order by course_name asc, chapter_code asc, id asc

select grouped.id, grouped.catalog_code as catalogCode, grouped.catalog_name as catalogName, grouped.course_name as courseName, grouped.chapter_code as chapterCode, grouped.chapter_name as chapterName, grouped.question_count as questionCount from ( select min(normalized.id) as id, concat('QB-', normalized.catalog_chapter_code) as catalog_code, normalized.chapter_name as catalog_name, normalized.course_name as course_name, normalized.chapter_code as chapter_code, normalized.chapter_name as chapter_name, count(1) as question_count from ( select qb.id, ifnull(nullif(qb.course_name, ''), 'Unnamed Course') as course_name, ifnull(nullif(qb.chapter_code, ''), '') as chapter_code, ifnull(nullif(qb.chapter_code, ''), 'NO_CODE') as catalog_chapter_code, ifnull(nullif(qb.chapter_name, ''), 'Unnamed Module') as chapter_name from edu_question_bank qb where qb.status = '0'
and qb.course_name = #{courseName}
) normalized group by normalized.course_name, normalized.chapter_code, normalized.catalog_chapter_code, normalized.chapter_name ) grouped order by grouped.course_name asc, grouped.chapter_code asc, grouped.id asc

select min(ar.id) as id, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, count(1) as answerCount from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}
and qb.course_name is not null and qb.course_name != '' and qb.chapter_name is not null and qb.chapter_name != ''
and qb.course_name = #{courseName}
group by qb.course_name, qb.chapter_code, qb.chapter_name order by qb.course_name asc, answerCount desc, qb.chapter_name asc

select id, course_name as courseName, chapter_code as chapterCode, chapter_name as chapterName, question_type as questionType, question_stem as questionStem, options_json as optionsJson, standard_answer as standardAnswer, analysis, knowledge_point as knowledgePoint, case when qb.difficulty_level is not null and qb.difficulty_level != '' then qb.difficulty_level when stats.correctRate is null then 'medium' when stats.correctRate < 40 then 'hard' when stats.correctRate < 75 then 'medium' else 'easy' end as difficultyLevel, ifnull(stats.correctRate, 0) as historicalCorrectRate from edu_question_bank qb left join ( select ar.question_id, round(avg(case when ar.is_correct = '1' then 100 else 0 end), 2) as correctRate from edu_student_answer_record ar group by ar.question_id ) stats on qb.id = stats.question_id where status = '0'
and qb.course_name = #{courseName}
and (
qb.chapter_code = #{chapterCode}
or
qb.chapter_name = #{chapterName}
)
and qb.question_type = #{questionType}
and ( case when qb.difficulty_level is not null and qb.difficulty_level != '' then qb.difficulty_level when stats.correctRate is null then 'medium' when stats.correctRate < 40 then 'hard' when stats.correctRate < 75 then 'medium' else 'easy' end ) = #{difficultyLevel}
order by rand() limit #{limit}

select qb.id as questionId, qb.course_name as courseName, qb.question_type as questionType, qb.chapter_code as chapterCode, qb.chapter_name as chapterName, qb.question_stem as questionStem, qb.options_json as optionsJson, qb.standard_answer as standardAnswer, qb.analysis as analysis, qb.knowledge_point as knowledgePoint, qb.difficulty_level as difficultyLevel, count(ar.id) as attemptCount, sum(case when ar.is_correct = '1' then 1 else 0 end) as correctCount from edu_question_bank qb left join edu_student_answer_record ar on qb.id = ar.question_id and ar.student_no = #{studentNo} where qb.status = '0'
and qb.course_name = #{courseName}
and (
qb.chapter_code = #{chapterCode}
or
qb.chapter_name = #{chapterName}
)
group by qb.id, qb.course_name, qb.question_type, qb.chapter_code, qb.chapter_name, qb.question_stem, qb.options_json, qb.standard_answer, qb.analysis, qb.knowledge_point, qb.difficulty_level order by correctCount asc, attemptCount asc, qb.id asc limit #{limit}

select ar.id, ar.question_id as questionId, ar.question_type as questionType, ar.answer_content as answerContent, ar.score, ar.is_correct as isCorrect, ar.submit_time as submitTime, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, qb.question_stem as questionStem, qb.standard_answer as standardAnswer, qb.analysis, qb.knowledge_point as knowledgePoint from edu_student_answer_record ar left join edu_question_bank qb on ar.question_id = qb.id where ar.student_no = #{studentNo}
and qb.course_name = #{courseName}
and (qb.chapter_code = #{chapterCode} or qb.chapter_name = #{chapterCode})
and ar.question_type = #{questionType}
order by ar.submit_time desc, ar.id desc limit #{limit}

select min(ar.id) as id, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, count(1) as answerCount from edu_student_answer_record ar left join edu_question_bank qb on ar.question_id = qb.id where ar.student_no = #{studentNo} and qb.course_name is not null and qb.course_name != ''
and qb.course_name = #{courseName}
group by qb.course_name, qb.chapter_code, qb.chapter_name order by qb.course_name asc, qb.chapter_code asc, answerCount desc

select count(distinct sp.student_no) as studentCount, count(1) as answerCount, round(ifnull(avg(case when ar.is_correct = '1' then 100 else 0 end), 0), 2) as correctRate, count(distinct case when qb.knowledge_point is not null and qb.knowledge_point != '' then qb.knowledge_point end) as knowledgePointCount from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}

select qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, count(distinct sp.student_no) as studentCount, count(1) as answerCount, sum(case when ar.is_correct = '1' then 1 else 0 end) as correctCount, round(ifnull(avg(case when ar.is_correct = '1' then 100 else 0 end), 0), 2) as correctRate from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}
and qb.chapter_name is not null and qb.chapter_name != '' group by qb.course_name, qb.chapter_code, qb.chapter_name order by correctRate asc, answerCount desc

select sp.student_no as studentNo, sp.student_name as studentName, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, count(1) as answerCount, sum(case when ar.is_correct = '1' then 1 else 0 end) as correctCount, sum(case when ar.is_correct = '0' then 1 else 0 end) as wrongCount, round(ifnull(avg(case when ar.is_correct = '1' then 100 else 0 end), 0), 2) as correctRate, max(ar.submit_time) as latestSubmitTime from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}
and qb.chapter_name is not null and qb.chapter_name != '' group by sp.student_no, sp.student_name, qb.course_name, qb.chapter_code, qb.chapter_name order by sp.student_name asc, correctRate asc, answerCount desc limit #{limit}

select sp.student_no as studentNo, sp.student_name as studentName, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, count(1) as answerCount, sum(case when ar.is_correct = '1' then 1 else 0 end) as correctCount, sum(case when ar.is_correct = '0' then 1 else 0 end) as wrongCount, round(ifnull(avg(case when ar.is_correct = '1' then 100 else 0 end), 0), 2) as correctRate, max(ar.submit_time) as latestSubmitTime from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}
and qb.chapter_name is not null and qb.chapter_name != ''
and sp.student_name like concat('%', #{studentName}, '%')
and qb.course_name = #{courseName}
and (qb.chapter_code = #{chapterCode} or qb.chapter_name = #{chapterCode})
group by sp.student_no, sp.student_name, qb.course_name, qb.chapter_code, qb.chapter_name order by sp.student_name asc, answerCount desc, correctRate asc

select ar.id, sp.student_no as studentNo, sp.student_name as studentName, ar.question_type as questionType, ar.answer_content as answerContent, ar.score, ar.is_correct as isCorrect, ar.submit_time as submitTime, qb.course_name as courseName, ifnull(nullif(qb.chapter_code, ''), qb.chapter_name) as chapterCode, qb.chapter_name as chapterName, qb.question_stem as questionStem, qb.standard_answer as standardAnswer, qb.analysis, qb.knowledge_point as knowledgePoint from edu_student_answer_record ar join legacy_staging_student_profile sp on ar.student_no = sp.student_no left join edu_question_bank qb on ar.question_id = qb.id where sp.class_code in
#{code}
and qb.course_name in
#{course}
and sp.student_no = #{studentNo} order by ar.submit_time desc, ar.id desc limit #{limit}

select sp.student_no as studentNo, sp.student_name as studentName, sp.class_code as classCode from legacy_staging_student_profile sp where sp.class_code in
#{code}
and sp.student_no = #{studentNo} limit 1
